import json
from jsonschema import validate, ValidationError

# Stubbed context (in production: pull from env/prior steps; replace with actual chat data)
context = {
    'chatId': '17',
    'date': '2026-01-07',
    'overview': 'Optimized chat summary schema/generation in handoff workflow: short keys, structured ov, omit empties, human expansion',
    'keyAchievements': ['Defined efficient schema with short keys/structured ov for AI parsing', 'Updated generation/validation with auto-fixes/truncation for <200 tokens', 'Added human-readable expansion step for dashboard/reviews', 'Simulated/tested workflow; reduced tokens by 17-30%'],
    'decisionsMade': ['Prioritize structured ov over prose for inference efficiency', 'Omit empties/optional fields to minimize size', 'Integrate formatter in ai-generate.ts for Phase 1 patterns', 'Add verbose_mode flag for backward compat'],
    'openTodos': [],
    'nextSteps': ['Test full end-to-end handoff in new chat', 'Validate Supabase upsert for Phase 1 dashboard aggregation'],
    'contextReminders': ['Enki Phase 1: Complement tools via upload/parse/generate; focus risk reduction/profit protection in PM lifecycle'],
    'parentChatId': '16',
    'priorSummaries': [],
    'incompleteStatus': {'automationsTested': ['schema', 'generation', 'validation', 'expansion', 'simulation'], 'automationsPending': []},
    'continuationFlag': True
}

# Minify and structure
summary = {
    'id': context['chatId'],
    'dt': context['date'],
    'ov': {
        'changes': [context['overview'][:100] + '...' if len(context['overview']) > 100 else context['overview']],
        'branch': 'refactor-phase1-flatten',
        'files': ['Revised Full Handoff Workflow.json', 'apps_web_lib_schemas_optimized-chat-summary.ts', 'apps_web_lib_ai-generate.ts'],
        'next_action': context['nextSteps'][0][:100] + '...' if context['nextSteps'] and len(context['nextSteps'][0]) > 100 else context['nextSteps'][0] if context['nextSteps'] else ''
    },
    'achvs': [item[:100] for item in context['keyAchievements'][:5]],
    'decs': [item[:100] for item in context['decisionsMade'][:5]],
    'nxt': [item[:100] for item in context['nextSteps'][:5]],
    'ctx': [item[:100] for item in context['contextReminders'][:5]],
    'pid': context['parentChatId'],
    'stat': {
        'tested': context['incompleteStatus']['automationsTested'],
        'pend': context['incompleteStatus']['automationsPending']
    },
    'cont': context['continuationFlag'],
    'schema_version': 'v2-opt'
}

# Omit empties
if context['openTodos']:
    summary['todos'] = [{'desc': todo['description'], 'pri': todo['priority']} for todo in context['openTodos']]
if context['priorSummaries']:
    summary['priors'] = context['priorSummaries']

# Optimized schema
optimized_schema = {
  'type': 'object',
  'properties': {
    'id': {'type': 'string'},
    'dt': {'type': 'string'},
    'ov': {
      'type': 'object',
      'properties': {
        'changes': {'type': 'array', 'items': {'type': 'string'}},
        'branch': {'type': 'string'},
        'files': {'type': 'array', 'items': {'type': 'string'}},
        'next_action': {'type': 'string'}
      },
      'required': ['changes', 'next_action']
    },
    'achvs': {'type': 'array', 'items': {'type': 'string'}},
    'decs': {'type': 'array', 'items': {'type': 'string'}},
    'todos': {
      'type': 'array',
      'items': {
        'type': 'object',
        'properties': {
          'desc': {'type': 'string'},
          'pri': {'type': 'string'}
        }
      }
    },
    'nxt': {'type': 'array', 'items': {'type': 'string'}},
    'ctx': {'type': 'array', 'items': {'type': 'string'}},
    'pid': {'type': ['string', 'null']},
    'priors': {'type': 'array', 'items': {'type': 'object'}},
    'stat': {
      'type': 'object',
      'properties': {
        'tested': {'type': 'array', 'items': {'type': 'string'}},
        'pend': {'type': 'array', 'items': {'type': 'string'}}
      }
    },
    'cont': {'type': 'boolean'},
    'schema_version': {'type': 'string'}
  },
  'required': ['id', 'dt', 'ov', 'achvs', 'decs', 'nxt', 'ctx', 'pid', 'stat', 'cont']
}

# Validate and fix
try:
    validate(instance=summary, schema=optimized_schema)
except ValidationError as e:
    for k in ['achvs', 'decs', 'nxt', 'ctx']:
        if k in summary:
            summary[k] = [item[:50] for item in summary[k][:3]]
    if 'ov' in summary and len(summary['ov']['next_action']) > 50:
        summary['ov']['next_action'] = summary['ov']['next_action'][:47] + '...'
    if 'todos' in summary and not summary['todos']:
        del summary['todos']
    if 'priors' in summary and not summary['priors']:
        del summary['priors']
    validate(instance=summary, schema=optimized_schema)
print(json.dumps(summary))
